mapper.select:
SELECT F.TARGETID AS TARGETID, T.OLDVALUE AS NAME FROM T_CORE_AUDIT_LOG_COLUMN T JOIN (SELECT MAX(A.ID) AS ID FROM T_CORE_AUDIT_LOG_COLUMN A JOIN T_CORE_AUDIT_LOG_ACTIVITY B ON A.ACTIVITYID = B.ID JOIN T_CORE_AUDIT_LOG C ON B.LOGID = C.ID WHERE A."COLUMN" = #{nameField} AND C.TARGETTABLE = #{tableName} AND C.TARGETID IN
#{item}
AND B.ACTIVITY = 'AUDIT.DELETE' GROUP BY C.TARGETID) D ON T.ID = D.ID JOIN T_CORE_AUDIT_LOG_ACTIVITY E ON T.ACTIVITYID = E.ID JOIN T_CORE_AUDIT_LOG F ON E.LOGID = F.ID
